begin;
on conflict (tipo,numero,ano) do update set titulo=excluded.titulo,data_catalogo=excluded.data_catalogo,autor=excluded.autor,resumo=excluded.resumo,origem=excluded.origem,coleta=excluded.coleta,pdf_url=excluded.pdf_url,pdf_observacao=excluded.pdf_observacao,campo_busca=excluded.campo_busca;
-- Compatibilidade: preservar os dois links existentes sem presumir a categoria.
select id,pdf_url,'PDF identificado','nao_classificado',pdf_observacao,coleta
from public.trt16_atos where pdf_url is not null
on conflict (url) do nothing;
commit;
